func TestRenameActivity(t *testing.T) {
	env := newTestEnv(t)
	id := env.importFixtures(t, 1)[0]
	post := func(htmx bool, name string) *httptest.ResponseRecorder {
		r := httptest.NewRequest(http.MethodPost, "/activities/"+itoa(id)+"/name", strings.NewReader(url.Values{"name": {name}}.Encode()))
		r.Header.Set("Content-Type", "application/x-www-form-urlencoded")
		if htmx {
			r.Header.Set("HX-Request", "true")
		}
		return env.do(r)
	}
	if w := post(false, "x"); w.Code != http.StatusForbidden {
		t.Errorf("without HX-Request: %d", w.Code)
	}
	w := post(true, "Feierabend <Runde>")
	if w.Code != http.StatusOK || !strings.Contains(w.Body.String(), "Feierabend &lt;Runde&gt;") || strings.Contains(w.Body.String(), "<html") {
		t.Errorf("rename fragment %d: %s", w.Code, w.Body.String())
	}
	if !strings.Contains(env.do(ingressGET("/activities")).Body.String(), "Feierabend &lt;Runde&gt;") {
		t.Error("list should show the new name")
	}
	if w := post(true, strings.Repeat("x", store.MaxNameLength+1)); w.Code != http.StatusUnprocessableEntity {
		t.Errorf("too long: %d", w.Code)
	}
}

