func TestStaticModulesAndCaching(t *testing.T) {
	env := newTestEnv(t)
	for path, want := range map[string]string{
		"/static/vendor/maplibre-gl-6.15.0/maplibre-gl.mjs":        "public, max-age=31536000, immutable",
		"/static/vendor/maplibre-gl-6.15.0/maplibre-gl-worker.mjs": "public, max-age=31536000, immutable",
		"/static/vendor/uplot-1.6.32/uPlot.esm.js":                 "public, max-age=31536000, immutable",
		"/static/activity.js":                                      "no-cache",
	} {
		w := env.do(httptest.NewRequest(http.MethodGet, path, nil))
		if w.Code != http.StatusOK {
			t.Errorf("%s: %d", path, w.Code)
			continue
		}
		// Browsers refuse ES modules without a JavaScript MIME type.
		if ct := w.Header().Get("Content-Type"); !strings.HasPrefix(ct, "text/javascript") {
			t.Errorf("%s: content type %q", path, ct)
		}
		if cc := w.Header().Get("Cache-Control"); cc != want {
			t.Errorf("%s: cache %q, want %q", path, cc, want)
		}
	}
}

